"""Shared mechanics for reusable task families: parsing, geometry kernels, rounding,
distractor selection, four-option validation and scoring. No model/API calls.

Families supply the science (what is asked, how the answer is computed, which
error mechanisms produce distractors); this module supplies the common checks so
that every family is validated the same way.
"""
import hashlib
import itertools
import math
from decimal import Decimal, ROUND_HALF_UP

LABELS = 'ABCD'
ELEMENTS = {'H', 'C', 'N', 'O', 'S', 'Cl', 'P', 'F', 'Zn', 'Si', 'Na', 'Mg', 'Cs', 'Br', 'I', 'Au', 'Cd', 'Se'}
COVALENT = {'H': 0.31, 'C': 0.76, 'N': 0.71, 'O': 0.66, 'S': 1.05, 'Cl': 1.02, 'P': 1.07,
            'F': 0.57, 'Zn': 1.22, 'Si': 1.11, 'Br': 1.20, 'I': 1.39}


def sha256(data):
    return hashlib.sha256(data if isinstance(data, bytes) else data.encode('utf-8')).hexdigest()


def parse_xyz(text, max_atoms=5000):
    """Strict XYZ: count line, comment line, exactly count rows of element x y z."""
    lines = text.splitlines()
    if len(lines) < 3:
        raise ValueError('XYZ requires count, comment and atom rows')
    try:
        n = int(lines[0].strip())
    except ValueError:
        raise ValueError('Invalid XYZ count')
    rows = [line.split() for line in lines[2:] if line.strip()]
    if n < 1 or n > max_atoms or len(rows) != n:
        raise ValueError('Atom count does not match rows')
    elements, points = [], []
    for row in rows:
        symbol = row[0].capitalize() if len(row) == 4 else ''   # e.g. PDB-style 'CL' -> 'Cl'
        if symbol not in ELEMENTS:
            raise ValueError('Expected known element and three coordinates')
        point = tuple(float(v) for v in row[1:])
        if not all(math.isfinite(v) for v in point):
            raise ValueError('Nonfinite coordinate')
        elements.append(symbol)
        points.append(point)
    return elements, points


def xyz_text(elements, points, comment):
    rows = ['%s %.8f %.8f %.8f' % (e, *p) for e, p in zip(elements, points)]
    return '\n'.join([str(len(rows)), comment] + rows) + '\n'


def sub(a, b):
    return [x - y for x, y in zip(a, b)]


def dot(a, b):
    return math.fsum(x * y for x, y in zip(a, b))


def cross(a, b):
    return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]]


def norm(a):
    return math.sqrt(dot(a, a))


def angle_acos(a, vertex, b):
    u, v = sub(a, vertex), sub(b, vertex)
    return math.degrees(math.acos(max(-1.0, min(1.0, dot(u, v) / (norm(u) * norm(v))))))


def angle_atan2(a, vertex, b):
    """Second implementation (atan2 of |u x v| and u.v), used as a cross-check."""
    u, v = sub(a, vertex), sub(b, vertex)
    return math.degrees(math.atan2(norm(cross(u, v)), dot(u, v)))


def dihedral_normals(p0, p1, p2, p3):
    """IUPAC signed torsion via plane normals, range (-180, 180]."""
    b1, b2, b3 = sub(p1, p0), sub(p2, p1), sub(p3, p2)
    n1, n2 = cross(b1, b2), cross(b2, b3)
    return math.degrees(math.atan2(norm(b2) * dot(b1, n2), dot(n1, n2)))


def dihedral_projection(p0, p1, p2, p3):
    """Second implementation: project outer bonds onto the plane normal to the axis."""
    b0, b1, b2 = sub(p0, p1), sub(p2, p1), sub(p3, p2)
    axis = [x / norm(b1) for x in b1]
    v = [x - dot(b0, axis) * y for x, y in zip(b0, axis)]
    w = [x - dot(b2, axis) * y for x, y in zip(b2, axis)]
    return math.degrees(math.atan2(dot(cross(axis, v), w), dot(v, w)))


def bond_graph(elements, points, scale=1.2):
    """Covalent-radius connectivity; an operational rule, stated in audits."""
    edges = set()
    for i, j in itertools.combinations(range(len(points)), 2):
        limit = scale * (COVALENT[elements[i]] + COVALENT[elements[j]])
        if math.dist(points[i], points[j]) <= limit:
            edges.add((i, j))
    return edges


def neighbors(edges, i):
    return sorted({b if a == i else a for a, b in edges if i in (a, b)})


def dmax(points):
    return max((math.dist(a, b) for a, b in itertools.combinations(points, 2)), default=0.0)


def display(value, decimals):
    quantum = Decimal(1).scaleb(-decimals)
    return str(Decimal(str(value)).quantize(quantum, rounding=ROUND_HALF_UP))


def digest(*parts):
    return hashlib.sha256('|'.join(map(str, parts)).encode('utf-8')).digest()


def ordered(items, seed, context, key=lambda x: x[0]):
    """Version-independent deterministic permutation keyed by seed and context."""
    return sorted(items, key=lambda x: digest(seed, context, key(x)))


def target_rank(seed, context):
    return 1 + digest(seed, context, 'rank')[0] % 4


def gap(a, b, period=None):
    """Absolute difference; for periodic quantities (torsions) the circular distance."""
    d = abs(a - b)
    if period is not None:
        period = Decimal(str(period))
        d = min(d % period, period - d % period)
    return d


def choose_numeric(correct, candidates, *, decimals, tolerance, min_separation, seed, context,
                   lower=None, upper=None, period=None, target=None, distractor_separation=None):
    """Pick three misconception distractors.

    candidates: dicts with rule, value, reason and plausibility (1 low .. 3 high).
    Among all valid triples (pairwise separated by more than min_separation and
    from the correct value) prefer the one whose correct-answer numeric rank equals
    a target rank (assigned per batch by the engine, else seeded), so that "always
    pick largest/smallest" does not work, then the most plausible mechanisms.
    min_separation applies to the correct value; distractor_separation (default the
    same) only keeps wrong options visibly distinct from each other.
    Returns (chosen, rejected, target, achieved rank).
    """
    tolerance, min_separation = Decimal(str(tolerance)), Decimal(str(min_separation))
    between = Decimal(str(distractor_separation)) if distractor_separation is not None else min_separation
    if between <= 2 * tolerance:
        raise ValueError('Distractors must not share tolerance intervals')
    if min_separation < 2 * tolerance:
        raise ValueError('Separation must exceed both tolerance intervals')
    right = Decimal(display(correct, decimals))
    valid, rejected = [], []
    for c in candidates:
        value = c['value']
        if value is None or not math.isfinite(float(value)):
            rejected.append(dict(rule=c['rule'], value=None, reason='not defined for this input'))
            continue
        shown = Decimal(display(value, decimals))
        if (lower is not None and shown < Decimal(str(lower))) or (upper is not None and shown > Decimal(str(upper))):
            rejected.append(dict(rule=c['rule'], value=str(shown), reason='outside the defined value range'))
        elif gap(shown, right, period) <= min_separation:
            rejected.append(dict(rule=c['rule'], value=str(shown), reason='too close to the correct value'))
        else:
            valid.append(dict(c, shown=shown))
    best = None
    goal = target if target is not None else target_rank(seed, context)
    for combo in itertools.combinations(valid, 3):
        values = [x['shown'] for x in combo]
        if any(gap(a, b, period) <= between for a, b in itertools.combinations(values, 2)):
            continue
        rank = 1 + sum(v < right for v in values)
        weak = sum(x.get('plausibility', 1) <= 1 for x in combo)   # easily dismissed option: worse than any rank miss
        mirror = right != 0 and any(x['shown'] == -right for x in combo)   # a '+/-' pair cue
        score = (abs(rank - goal) + 4 * weak + int(mirror), -sum(x.get('plausibility', 1) for x in combo),
                 digest(seed, context, *sorted(x['rule'] for x in combo)))
        if best is None or score < best[0]:
            best = (score, combo, rank)
    if best is None:
        raise ValueError('Fewer than three separated misconception distractors')
    chosen = list(best[1])
    names = {x['rule'] for x in chosen}
    for x in valid:
        if x['rule'] not in names:
            rejected.append(dict(rule=x['rule'], value=str(x['shown']), reason='valid but not selected (rank balance / plausibility)'))
    return chosen, rejected, goal, best[2]


def label_numeric(correct, chosen, *, decimals, unit, seed, context, correct_reason):
    """Options in ascending numeric order, so label position equals numeric rank;
    the balanced target rank therefore also balances answer positions."""
    entries = [('correct', display(correct, decimals), correct_reason)] +               [(x['rule'], str(x['shown']), x['reason']) for x in chosen]
    permutation = sorted(entries, key=lambda e: Decimal(e[1]))
    options = [{'label': l, 'value': v, 'unit': unit} for l, (_, v, _) in zip(LABELS, permutation)]
    audit = [{'label': l, 'rule': r, 'value': v, 'reason': why, 'is_correct': r == 'correct',
              'absolute_error': str(abs(Decimal(v) - Decimal(str(correct))))}
             for l, (r, v, why) in zip(LABELS, permutation)]
    return options, audit


def place(correct, others, target, seed, context, key):
    """Categorical options: others in seeded order, correct inserted at the target index."""
    rest = ordered(list(others), seed, context + '/labels', key=key)
    index = (target - 1) if target is not None else target_rank(seed, context) - 1
    return rest[:index] + [correct] + rest[index:]


def validate_numeric(options, expected, *, decimals, tolerance, min_separation, unit, period=None,
                     distractor_separation=None):
    if len(options) != 4 or [o['label'] for o in options] != list(LABELS):
        raise ValueError('Exactly A/B/C/D required')
    values = [Decimal(o['value']) for o in options]
    if any(o['unit'] != unit or not v.is_finite() or o['value'] != display(v, decimals) for o, v in zip(options, values)):
        raise ValueError('Invalid unit, value or precision')
    between = Decimal(str(distractor_separation if distractor_separation is not None else min_separation))
    if any(gap(a, b, period) <= between for a, b in itertools.combinations(values, 2)):
        raise ValueError('Options not separated')
    hits = [o['label'] for o, v in zip(options, values) if gap(v, Decimal(str(expected)), period) <= Decimal(str(tolerance))]
    if len(hits) != 1:
        raise ValueError('Not exactly one correct option')
    right = values[[o['label'] for o in options].index(hits[0])]
    if any(gap(v, right, period) <= Decimal(str(min_separation)) for v in values if v is not right):
        raise ValueError('A distractor is too close to the correct value')
    return hits[0]


def validate_verdicts(options, verdicts, key=lambda o: o['value']):
    """Categorical options: all four verified by the family checker, exactly one true."""
    if len(options) != 4 or [o['label'] for o in options] != list(LABELS):
        raise ValueError('Exactly A/B/C/D required')
    if len({repr(key(o)) for o in options}) != 4:
        raise ValueError('Duplicate options')
    if len(verdicts) != 4 or any(v not in (True, False) for v in verdicts):
        raise ValueError('Every option needs a verified verdict')
    hits = [o['label'] for o, v in zip(options, verdicts) if v]
    if len(hits) != 1:
        raise ValueError('Not exactly one correct option')
    return hits[0]


def score_choice(response, correct):
    if correct not in LABELS or len(correct) != 1:
        raise ValueError('Invalid answer key')
    return isinstance(response, str) and response.strip().upper() == correct


def score_numeric(response, expected, tolerance, unit):
    if not isinstance(response, dict) or set(response) != {'value', 'unit'}:
        return False
    value = response['value']
    if type(value) not in (int, float) or response['unit'] != unit or not math.isfinite(value):
        return False
    return abs(Decimal(str(value)) - Decimal(str(expected))) <= Decimal(str(tolerance))


def mirror_pair_cue(option_values, correct_label):
    """True when the correct value's negation is also an option (a test-wise cue)."""
    values = dict(option_values)
    right = Decimal(values[correct_label])
    return right != 0 and any(Decimal(v) == -right for l, v in option_values if l != correct_label)


def rank_shortcuts(option_values, correct_label):
    """Option-only baselines: which label would 'largest', 'smallest', 'second' pick."""
    order = sorted(option_values, key=lambda x: Decimal(x[1]))
    picks = {'always_smallest': order[0][0], 'always_second': order[1][0],
             'always_third': order[2][0], 'always_largest': order[3][0]}
    return {k: v == correct_label for k, v in picks.items()}

"""Shared helpers for independent answer checkers.

Independence rule: nothing under checkers/ imports the question-generation code
(task_families, family_engine, template_engine, choice_engine or tools). A checker
sees only what the tested model sees (question text, attached inputs, options) plus
the answer key, and recomputes with its own implementation. Provenance checks may
read the public source asset named in the answer key and verify its SHA-256.
"""
import hashlib
import math
import re
from decimal import Decimal, ROUND_HALF_UP, localcontext
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
VERSION = '0.1.0'
LABELS = ['A', 'B', 'C', 'D']
# Answer-key vocabulary that must never appear in a student packet.
FORBIDDEN_KEYS = {'correct_label', 'is_correct', 'option_audit', 'reason', 'source_id', 'numeric_answer',
                  'explanation', 'excluded_candidates', 'rank', 'checks'}


class CheckError(Exception):
    """A check that fails; the message is reported verbatim."""


def need(condition, message):
    if not condition:
        raise CheckError(message)


def find(pattern, text, message, flags=0):
    match = re.search(pattern, text, flags)
    need(match is not None, message)
    return match


def read_xyz(text):
    """Returns [(element, (Decimal x, y, z))]; strict count and row format."""
    lines = text.splitlines()
    need(len(lines) >= 3 and lines[0].strip().isdigit(), 'XYZ header invalid')
    rows = [line.split() for line in lines[2:] if line.strip()]
    need(len(rows) == int(lines[0]), 'XYZ atom count does not match rows')
    atoms = []
    for row in rows:
        need(len(row) == 4 and row[0].isalpha(), 'XYZ row must be element x y z')
        coords = tuple(Decimal(v) for v in row[1:])
        need(all(c.is_finite() for c in coords), 'Nonfinite coordinate')
        atoms.append((row[0].capitalize(), coords))
    return atoms


def dist(p, q):
    with localcontext() as ctx:
        ctx.prec = 40
        return sum((a - b) ** 2 for a, b in zip(p, q)).sqrt()


def vec(p, q):
    """q - p as floats."""
    return [float(b) - float(a) for a, b in zip(p, q)]


def dot(u, v):
    return math.fsum(a * b for a, b in zip(u, v))


def cross(u, v):
    return [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]]


def rounded(value, decimals):
    return Decimal(str(value)).quantize(Decimal(1).scaleb(-decimals), rounding=ROUND_HALF_UP)


def sha256_file(rel):
    path = (ROOT / 'docs' / rel).resolve()
    need(path.is_relative_to((ROOT / 'docs/assets').resolve()), 'Evidence asset outside docs/assets')
    need(path.exists(), 'Evidence asset missing: ' + rel)
    return hashlib.sha256(path.read_bytes()).hexdigest(), path


def verify_hashes(key):
    """Every reviewer-side asset named in the key must match its recorded SHA-256."""
    paths = {}
    for rel, digest in key['input_hashes'].items():
        actual, path = sha256_file(rel)
        need(actual == digest, 'Asset hash mismatch: ' + rel)
        paths[rel] = path
    return paths


def packet_shape(packet):
    need([o['label'] for o in packet['options']] == LABELS, 'Options must be exactly A, B, C, D')
    need(len({o['value'] for o in packet['options']}) == 4, 'Duplicate option values')
    leaked = FORBIDDEN_KEYS & _keys(packet)
    need(not leaked, 'Answer-key fields in student packet: ' + ', '.join(sorted(leaked)))


def _keys(obj):
    if isinstance(obj, dict):
        return set(obj) | set().union(*(_keys(v) for v in obj.values()))
    if isinstance(obj, list):
        return set().union(*(_keys(v) for v in obj)) if obj else set()
    return set()


def gap(a, b, period=None):
    d = abs(a - b)
    if period is not None:
        d = min(d % period, period - d % period)
    return d


def judge_numeric(packet, key, value, period=None):
    """Recomputed value vs. options and key: exactly one option equals the rounded value,
    the other three lie outside the tolerance, and key label / numeric key agree."""
    numeric = key['numeric_answer']
    decimals, tol = numeric['decimals'], Decimal(numeric['tolerance'])
    expected = rounded(value, decimals)
    exact = Decimal(repr(value)) if isinstance(value, float) else Decimal(value)
    units = {o.get('unit') for o in packet['options']}
    need(units == {numeric['unit']}, 'Option units differ from the answer unit')
    for o in packet['options']:
        need(re.fullmatch(r'-?\d+\.\d{%d}' % decimals if decimals else r'-?\d+', o['value']) is not None,
             'Option %s not shown with %d decimals' % (o['label'], decimals))
    hits = [o['label'] for o in packet['options'] if gap(Decimal(o['value']), exact, period) <= tol]
    need(len(hits) == 1, 'Recomputed value matches %d options (need exactly 1)' % len(hits))
    label = hits[0]
    shown = next(o['value'] for o in packet['options'] if o['label'] == label)
    need(Decimal(shown) == expected or (period and gap(Decimal(shown), expected, period) == 0),
         'Matching option %s is not the rounded recomputed value %s' % (shown, expected))
    need(Decimal(numeric['value']) == expected, 'Numeric key %s != recomputed %s' % (numeric['value'], expected))
    need(key['correct_label'] == label, 'Key label %s != recomputed label %s' % (key['correct_label'], label))
    nearest = min(gap(Decimal(o['value']), exact, period) for o in packet['options'] if o['label'] != label)
    q = Decimal('1e-10')
    return dict(recomputed=str(exact.quantize(q)), rounded=str(expected), label=label,
                nearest_distractor_gap=str(nearest.quantize(q)))

"""Independent answer checkers (see common.py for the independence rule)."""
from .common import CheckError, VERSION, packet_shape
from .families import CHECKERS


def check(packet, key):
    """Returns a report dict; status is 'pass' only if every check succeeded."""
    report = dict(id=packet['id'], family=packet['family'], checker_version=VERSION)
    try:
        if packet['id'] != key['id'] or packet['family'] != key['family']:
            raise CheckError('Packet and key do not belong together')
        if packet['family'] not in CHECKERS:
            raise CheckError('No independent checker for family ' + packet['family'])
        if not key.get('input_hashes'):
            raise CheckError('No source asset recorded in the answer key')
        packet_shape(packet)
        report.update(CHECKERS[packet['family']](packet, key))
        report['status'] = 'pass'
    except CheckError as error:
        report.update(status='fail', problem=str(error))
    except (KeyError, ValueError, IndexError, ArithmeticError) as error:
        report.update(status='fail', problem='Malformed packet or key: %s: %s' % (type(error).__name__, error))
    return report

"""Instance enumerators: propose every candidate instance a structure offers.

A family's build function already decides whether one instance is admissible (unique answer,
separated options, chain continuity, windows and margins). An enumerator only proposes specs:
every residue, every residue pair, every candidate set built around an admissible answer.
tools/enumerate_instances.py builds the proposals, keeps the ones the family accepts and runs
the independent checkers on them. Enumerators may compute geometry to pre-select promising
proposals (e.g. a pair inside the disulfide windows), but the answer, the options and every
admissibility check are decided by the family's build function and re-verified by the
independent checker; a proposal the family rejects is simply dropped.

Structures come from templates/structures.json (assets already committed with source and licence).
This module lives outside task_families/ on purpose: it writes manifests (which every run snapshots
and hashes) and does not change how any question is built.
"""
import json
import math

from task_families import kit
from task_families.local_geometry import read_pdb_residues
from task_families.protein_design import CA_WINDOW, CB_WINDOW, MARGIN, efficiency

STRUCTURES = 'templates/structures.json'
R0_CHOICES = (2.0, 2.5, 3.0, 4.0, 5.0, 6.0)            # nm; stated in the question as a model parameter
TARGETS = (0.25, 0.5, 0.75)                             # FRET design targets
MIN_SPACING = 3                                         # residues apart for any pair
SCOPE = {
    'backbone_torsion': '只含残基 %d–%d 的 ATOM 记录；无替代构象；按 IUPAC 符号约定。',
    'secondary_structure': '只含残基 %d–%d 的 ATOM 记录；参考构象中心为教科书典型值；条目的 HELIX/SHEET 记录作为审核证据，不给考生。',
    'fret_efficiency': '虚拟点探针（R0 为题设值）；不代表真实染料位置、连接臂或取向分布。',
    'disulfide_design': 'ATOM 片段逐行照抄；筛选窗口为题干给出的几何标准；不评估二面角与稳定性。',
    'fret_design': 'ATOM 片段逐行照抄；点偶极、R0 为题设模型参数（取向因子含于 R0）。',
}


def load_structures(root):
    return json.loads((root / STRUCTURES).read_text(encoding='utf-8'))['structures']


def residues_of(root, s):
    text = (root / 'docs' / s['asset']).read_text(encoding='utf-8')
    residues, order, altloc = read_pdb_residues(text, s['chain'])
    return residues, [n for n in order if n not in altloc]


def base(s, family, key, scope):
    return dict(id='EN-%s-%s' % (s['pdb'], key), family=family, asset=s['asset'], pdb=s['pdb'], chain=s['chain'],
                context=s['context'], source=s['source'], license=s['license'], scope=scope)


def pick_r0(r, *context):
    """A stated Förster radius with 0.6 <= r/R0 <= 1.6 (efficiencies away from 0 and 1), chosen by hash so that
    r falls on both sides of R0. Always taking the nearest R0 left r < R0 in most proposals, where nearly every
    misconception gives a smaller efficiency and the correct option became the largest one (found by the
    capacity probe, runs/enum-v01). None if no stated value fits."""
    fits = [x for x in R0_CHOICES if 0.6 <= r / x <= 1.6]
    return min(fits, key=lambda x: kit.digest('r0', *context, str(x))) if fits else None


def pairs_by_atom(residues, numbers, atom):
    pts = [(n, residues[n]['atoms'][atom]) for n in numbers if atom in residues[n]['atoms']]
    for a in range(len(pts)):
        for b in range(a + 1, len(pts)):
            (i, p), (j, q) = pts[a], pts[b]
            if j - i >= MIN_SPACING:
                yield i, j, math.dist(p, q) / 10


# ------------------------------------------------------------------ per-residue families
def backbone_torsion(root, s):
    if s['kind'] != 'protein':
        return
    residues, numbers = residues_of(root, s)
    for n in numbers:
        for kind in ('phi', 'psi'):
            yield dict(base(s, 'backbone_torsion', 'TOR-%d-%s' % (n, kind.upper()), SCOPE['backbone_torsion'] % (n - 1, n + 1)),
                       residue=n, torsion=kind)


def secondary_structure(root, s):
    if s['kind'] != 'protein':
        return
    residues, numbers = residues_of(root, s)
    for n in numbers:
        yield dict(base(s, 'secondary_structure', 'SS-%d' % n, SCOPE['secondary_structure'] % (n - 1, n + 1)), residue=n)


# ------------------------------------------------------------------ pair families
def fret_efficiency(root, s):
    residues, numbers = residues_of(root, s)
    atom = 'CA' if s['kind'] == 'protein' else "C1'"
    for i, j, r in pairs_by_atom(residues, numbers, atom):
        fits = [x for x in R0_CHOICES if 0.6 <= r / x <= 1.6]
        # Stated R0 values on both sides of r, so the family can reach every answer rank (see scattering.build_fret).
        if r >= 1.0 and any(x < r for x in fits) and any(x > r for x in fits):   # reasoning scale = r: 1-10 nm cell
            yield dict(base(s, 'fret_efficiency', 'FRET-%d-%d' % (i, j), SCOPE['fret_efficiency']),
                       donor=[i, atom], acceptor=[j, atom], R0_choices=fits, path_atom=atom)


def disulfide_rows(residues, numbers):
    rows = []
    usable = [n for n in numbers if residues[n]['name'] not in ('CYS', 'GLY') and {'CA', 'CB'} <= set(residues[n]['atoms'])]
    for a in range(len(usable)):
        for b in range(a + 1, len(usable)):
            i, j = usable[a], usable[b]
            if j - i < MIN_SPACING:
                continue
            ra, rb = residues[i]['atoms'], residues[j]['atoms']
            dca, dcb = math.dist(ra['CA'], rb['CA']), math.dist(ra['CB'], rb['CB'])
            miss_ca = max(CA_WINDOW[0] - dca, dca - CA_WINDOW[1], 0)
            miss_cb = max(CB_WINDOW[0] - dcb, dcb - CB_WINDOW[1], 0)
            if miss_ca == 0 and miss_cb == 0:
                kind = 'pass'
            elif 0 < max(miss_ca, miss_cb) < MARGIN:
                continue                                      # too close to a window: the family rejects such sets
            elif miss_ca == 0:
                kind = 'calpha_only'
            elif miss_cb == 0:
                kind = 'cbeta_only'
            elif dca <= 9.0:
                kind = 'both_out'                             # plausible neighbours only
            else:
                continue
            rows.append(dict(pair=[i, j], kind=kind))
    return rows


def disulfide_design(root, s):
    """One proposal per admissible pair: the pair plus one distractor of each failure kind where available."""
    if s['kind'] != 'protein':
        return
    residues, numbers = residues_of(root, s)
    rows = disulfide_rows(residues, numbers)
    failing = {k: [r['pair'] for r in rows if r['kind'] == k] for k in ('calpha_only', 'cbeta_only', 'both_out')}
    for good in (r['pair'] for r in rows if r['kind'] == 'pass'):
        picks = []
        for kind in ('calpha_only', 'cbeta_only', 'both_out'):
            pool = sorted(failing[kind], key=lambda p: kit.digest(s['pdb'], str(good), str(p)))
            picks += pool[:1]
        rest = sorted([p for k in failing for p in failing[k] if p not in picks], key=lambda p: kit.digest(s['pdb'], str(good), 'fill', str(p)))
        picks += rest[:3 - len(picks)]
        if len(picks) == 3:
            yield dict(base(s, 'disulfide_design', 'DS-%d-%d' % tuple(good), SCOPE['disulfide_design']), pairs=[good] + picks)


def fret_design(root, s):
    """For each target, each pair whose efficiency is within 0.03 of the target, plus three pairs clearly farther away."""
    residues, numbers = residues_of(root, s)
    atom = 'CA' if s['kind'] == 'protein' else 'P'
    pairs = [(i, j, r) for i, j, r in pairs_by_atom(residues, numbers, atom) if 1.0 <= r < 10]
    for t in TARGETS:
        for i, j, r in pairs:
            r0 = pick_r0(r, s['pdb'], str(t), str(i), str(j))
            if not r0 or abs(efficiency(r, r0) - t) > 0.03:
                continue
            d = abs(efficiency(r, r0) - t)
            far = [(a, b) for a, b, q in pairs if {a, b}.isdisjoint({i, j}) and abs(efficiency(q, r0) - t) >= max(1.5 * d, d + 0.05) + 0.02]
            far.sort(key=lambda p: kit.digest(s['pdb'], str(t), str((i, j)), str(p)))
            if len(far) >= 3:
                spec = dict(base(s, 'fret_design', 'FD-%02d-%d-%d' % (round(t * 100), i, j), SCOPE['fret_design']),
                            atom=atom, r0_nm=r0, target=t, pairs=[[i, j]] + [list(p) for p in far[:3]])
                if s['kind'] == 'nucleic':
                    spec['nucleic'] = True
                yield spec


ENUMERATORS = dict(backbone_torsion=backbone_torsion, secondary_structure=secondary_structure, fret_efficiency=fret_efficiency,
                   disulfide_design=disulfide_design, fret_design=fret_design)


def propose(root, families=None):
    """{family: [spec, ...]} over every structure; ids are unique and deterministic."""
    out = {}
    for family, fn in ENUMERATORS.items():
        if families and family not in families:
            continue
        out[family] = [spec for s in load_structures(root) for spec in fn(root, s)]
    return out


def signature(spec):
    """What makes two instances the same question, independent of id and wording."""
    keys = ('family', 'asset', 'chain', 'residue', 'torsion', 'donor', 'acceptor', 'target', 'r0_nm', 'atom')
    sig = {k: spec.get(k) for k in keys}
    if spec.get('pairs'):
        sig['pairs'] = sorted(sorted(p) for p in spec['pairs'])
    return json.dumps(sig, sort_keys=True)

"""Select the 160-question prototype (10 per domain x reasoning-scale cell) from the active catalog.

  python tools/select_prototype.py            # -> docs/data/prototype-selection.json

The rule lives in templates/prototype-selection-rule.json and is a proposal pending the professor. Selection is
deterministic: independently checked questions first, abilities balanced towards 3/3/3, then questions outside the
pending-decision groups, review-unit and source diversity, and finally SHA-256(seed|id). Unselected active questions
become reserve; nothing in the catalog is changed.
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
import review_system as rs  # noqa: E402

DOMAINS = ('chemistry', 'biology', 'materials', 'quantum')
CELLS = ('0.1-1', '1-10', '10-100', '100-1000')
TIER = {'family': 0, 'family-version': 0, 'legacy': 1}
TIER_LABEL = {0: '经独立检查（题型族实例或旧题的四选一版本）', 1: '旧模板题'}


def read(rel):
    return json.loads((ROOT / rel).read_text(encoding='utf-8'))


def pending(item, rule):
    for key, g in rule['pending_decision'].items():
        if item['unit'] in g['families'] or any((item['instance'] or '').startswith(p) for p in g['instance_prefixes']):
            return key
    return None


def candidates(catalog, rule):
    out = []
    for it in rs.instances(catalog):
        out.append(dict(it, tier=TIER[it['form']], pending=pending(it, rule)))
    return out


def pick(cands, rule, chosen):
    """Greedy balanced pick within one tier; chosen is extended in place."""
    order = rule['abilities']
    count = {a: sum(c['ability'] == a for c in chosen) for a in order}
    units, sources = {}, {}
    for c in chosen:
        units[c['unit']] = units.get(c['unit'], 0) + 1
        sources[c['source']] = sources.get(c['source'], 0) + 1
    left = list(cands)
    while len(chosen) < rule['per_cell'] and left:
        avail = {c['ability'] for c in left}
        a = min(avail, key=lambda x: (count[x], order.index(x)))
        c = min((c for c in left if c['ability'] == a),
                key=lambda c: (c['pending'] is not None, units.get(c['unit'], 0), sources.get(c['source'], 0), rs.rank_key(rule['seed'], c['id'])))
        left.remove(c)
        chosen.append(c)
        count[a] += 1
        units[c['unit']] = units.get(c['unit'], 0) + 1
        sources[c['source']] = sources.get(c['source'], 0) + 1
    return chosen


def short(c):
    return {k: c[k] for k in ('id', 'ability', 'form', 'unit', 'instance', 'source', 'pending')}


def select(catalog, rule):
    by_cell = {}
    for c in candidates(catalog, rule):
        by_cell.setdefault(c['cell'], []).append(c)
    cells = []
    for d in DOMAINS:
        for b in CELLS:
            key = '%s %s' % (d, b)
            members = sorted(by_cell.get(key, []), key=lambda c: c['id'])
            ok = [c for c in members if c['l0']]
            chosen = []
            for tier in (0, 1):
                pick([c for c in ok if c['tier'] == tier], rule, chosen)
            ids = {c['id'] for c in chosen}
            tier0 = sum(c['tier'] == 0 for c in ok)
            notes = ['可用 %d 道，其中经独立检查 %d 道' % (len(ok), tier0)]
            legacy = [c['id'] for c in chosen if c['tier'] == 1]
            if legacy:
                notes.append('经独立检查的题不足 %d 道，用旧模板题补 %d 道：%s' % (rule['per_cell'], len(legacy), '、'.join(legacy)))
            gaps = [a for a in rule['abilities'] if not any(c['ability'] == a for c in chosen)]
            if gaps:
                notes.append('缺少能力：' + '、'.join(gaps))
            if len(chosen) < rule['per_cell']:
                notes.append('不足 %d 道' % rule['per_cell'])
            cells.append(dict(cell=key, domain=d, bin=b, available=len(members), eligible=len(ok),
                              abilities={a: sum(c['ability'] == a for c in chosen) for a in rule['abilities']},
                              selected=[short(c) for c in sorted(chosen, key=lambda c: (rule['abilities'].index(c['ability']), c['id']))],
                              reserve=[dict(short(c), reason='未通过 L0' if not c['l0'] else '本格已满 %d 道' % rule['per_cell'])
                                       for c in members if c['id'] not in ids],
                              rationale='；'.join(notes)))
    return cells


def build(catalog=None, rule=None):
    catalog = catalog or read('docs/data/catalog.json')
    rule = rule or read('templates/prototype-selection-rule.json')
    cells = select(catalog, rule)
    sel = [s for c in cells for s in c['selected']]
    res = [s for c in cells for s in c['reserve']]
    stray = sorted(c['id'] for c in candidates(catalog, rule) if c['cell'].split(' ')[1] == 'out-of-range')
    summary = dict(selected=len(sel), reserve=len(res), out_of_range=stray,
                   abilities={a: sum(s['ability'] == a for s in sel) for a in rule['abilities']},
                   forms={f: sum(s['form'] == f for s in sel) for f in TIER},
                   review_units=len({s['unit'] for s in sel}),
                   family_units=len({s['unit'] for s in sel if s['form'] != 'legacy'}),
                   legacy_units=len({s['unit'] for s in sel if s['form'] == 'legacy'}),
                   pending_decision={k: sum(s['pending'] == k for s in sel) for k in rule['pending_decision']},
                   full_cells=sum(len(c['selected']) == rule['per_cell'] for c in cells))
    return dict(kind='prototype_selection', rule_version=rule['version'], status=rule['status'], status_note=rule['status_note'],
                seed=rule['seed'], steps=rule['steps'],
                pending_labels={k: v['label'] for k, v in rule['pending_decision'].items()},
                summary=summary, cells=cells, selected_ids=sorted(s['id'] for s in sel))


def load_selected():
    path = ROOT / 'docs/data/prototype-selection.json'
    return set(json.loads(path.read_text(encoding='utf-8'))['selected_ids']) if path.exists() else None


if __name__ == '__main__':
    out = build()
    (ROOT / 'docs/data/prototype-selection.json').write_text(json.dumps(out, ensure_ascii=False, indent=1) + '\n', encoding='utf-8', newline='\n')
    print(json.dumps(out['summary'], ensure_ascii=False))
    for c in out['cells']:
        print(c['cell'], c['abilities'], c['rationale'])

